INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001cd',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss innovation at B2","Use Startup vocabulary","Talk about entrepreneurship"],"explanation":{"intro":"Innovation and startup vocabulary covers entrepreneurship, funding, and scaling at B2.","culturalNote":"Germany''s Startup-Ökosystem is centered in Berlin (nicknamed ''Silicon Allee''), Munich, and Hamburg. Key concepts: Gründung (founding), Seed-Finanzierung (seed funding), Series A/B, Exit (IPO or acquisition), Unicorn (Unicorn — startup valued >$1bn). Germany has ~400,000 Startups. Challenges: Bürokratie (bureaucracy), Risikokapitalmangel (venture capital shortage), risk aversion (Scheitern ist gesellschaftlich noch nicht akzeptiert — failure still stigmatised)."},"examples":[{"german":"Disruptive Innovationen stellen bestehende Geschäftsmodelle grundlegend in Frage und eröffnen neue Marktchancen.","english":"Disruptive innovations fundamentally call established business models into question and open up new market opportunities."},{"german":"Erfolgreiche Startups zeichnen sich durch eine starke Gründerpersönlichkeit, ein skalierbares Produkt und schnelles Lernen aus Fehlern aus.","english":"Successful startups are distinguished by a strong founder personality, a scalable product, and fast learning from mistakes."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss innovation, startups, and entrepreneurship at B2."}}',
'{"items":[{"word":"disruptiv","translation":"disruptive","pronunciation":"dis-roop-TEEF","example":"Disruptive Innovation."},{"word":"in Frage stellen","translation":"to call into question","pronunciation":"in FRAH-geh SHTEL-en","example":"In Frage stellen."},{"word":"eröffnen","translation":"to open up/create","pronunciation":"er-ÖF-nen","example":"Marktchancen eröffnen."},{"word":"skalierbar","translation":"scalable","pronunciation":"skah-LEER-bar","example":"Skalierbares Produkt."},{"word":"die Gründerpersönlichkeit","translation":"founder personality","pronunciation":"dee GRÜN-der-per-zön-likh-kyt","example":"Gründerpersönlichkeit."},{"word":"das Geschäftsmodell","translation":"business model","pronunciation":"dahs geh-SHEFTS-mo-del","example":"Geschäftsmodell."}]}',
'{"title":"In Frage stellen — to call into question","pattern":"etwas in Frage stellen = to call something into question, to challenge (separable idiom)","explanation":"In Frage stellen = to call into question, challenge, cast doubt on. Separable: stellt...in Frage. Perfect: hat in Frage gestellt. Compare: hinterfragen (to question critically), anzweifeln (to doubt), in Zweifel ziehen (to cast doubt on — formal). In Frage kommen = to be a possibility (different meaning!). Nicht in Frage kommen = to be out of the question.","examples":[{"sentence":"Die neuen Erkenntnisse stellen bisherige Annahmen in Frage.","translation":"The new findings call previous assumptions into question."},{"sentence":"Das kommt für uns nicht in Frage.","translation":"That is out of the question for us."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Skalierbar'' means?","options":["scalable","adjustable","flexible","expandable"],"correctAnswer":"scalable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Disruptive innovations fundamentally call established business models into question and open up new market opportunities.","options":["Disruptive Innovationen stellen bestehende Geschäftsmodelle grundlegend in Frage und eröffnen neue Marktchancen.","Innovationen verändern Märkte und Geschäftsmodelle.","Neue Technologien stellen alte Modelle in Frage.","Disruption eröffnet neue Chancen."],"correctAnswer":"Disruptive Innovationen stellen bestehende Geschäftsmodelle grundlegend in Frage und eröffnen neue Marktchancen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die neuen Erkenntnisse stellen bisherige Annahmen in ___.","options":["Frage","Zweifel","Fragen","frage"],"correctAnswer":"Frage"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That is out of the question for us","wordBankItems":["Das","kommt","für","uns","nicht","in","Frage","."],"correctAnswer":"Das kommt für uns nicht in Frage ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Disruptiv'' means?","options":["disruptive","destructive","innovative","radical"],"correctAnswer":"disruptive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001ce',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital transformation at B2","Use Digitalisierung vocabulary","Talk about Industry 4.0"],"explanation":{"intro":"Digital transformation vocabulary covers digitisation, automation, and Industry 4.0 at B2.","culturalNote":"Germany''s Digitalisierungsrückstand (digitisation lag) is a major concern — ranking low among OECD countries in digital public services. Key initiatives: Industrie 4.0 (smart manufacturing), Digitale Verwaltung (digital government), Glasfaserausbau (fibre broadband). Key terms: KI (AI), IoT (Internet der Dinge), Cloud Computing, Big Data, Automatisierung."},"examples":[{"german":"Die digitale Transformation erfasst alle Unternehmensbereiche und erfordert nicht nur technologische, sondern auch kulturelle Veränderungen.","english":"Digital transformation encompasses all areas of the company and requires not only technological but also cultural changes."},{"german":"Industrie 4.0 beschreibt die Vernetzung von Produktionsanlagen mit digitalen Systemen zu intelligenten Fabriken.","english":"Industry 4.0 describes the interconnection of production facilities with digital systems into smart factories."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital transformation, Industry 4.0, and digitisation at B2."}}',
'{"items":[{"word":"erfassen","translation":"to encompass/cover/capture","pronunciation":"er-FAS-en","example":"Alle Bereiche erfassen."},{"word":"die Vernetzung","translation":"interconnection/networking","pronunciation":"dee fer-NET-soong","example":"Vernetzung von Systemen."},{"word":"die Produktionsanlage","translation":"production facility","pronunciation":"dee pro-dook-TSYOHNS-an-lah-geh","example":"Produktionsanlagen."},{"word":"intelligent","translation":"smart/intelligent","pronunciation":"in-tel-ee-GENT","example":"Intelligente Fabrik."},{"word":"der Rückstand","translation":"lag/backlog","pronunciation":"dayr RÜK-shtant","example":"Digitalisierungsrückstand."},{"word":"kulturell","translation":"cultural","pronunciation":"kool-too-REL","example":"Kulturelle Veränderungen."}]}',
'{"title":"Nicht nur...sondern auch mit kulturellen Veränderungen — extending nicht nur","pattern":"erfordert nicht nur X, sondern auch Y = requires not only X but also Y (additive)","explanation":"Recap: nicht nur...sondern auch. Erfordert nicht nur technologische, sondern auch kulturelle Veränderungen = requires not only technological but also cultural changes. The nicht nur...sondern auch pair: both elements are true and equally important. This is extremely common in academic and journalistic German to show that a topic has multiple dimensions that must all be addressed.","examples":[{"sentence":"Der Wandel erfordert nicht nur neue Fähigkeiten, sondern auch eine neue Denkweise.","translation":"The change requires not only new skills but also a new mindset."},{"sentence":"Erfolg hängt nicht nur von Talent, sondern auch von harter Arbeit ab.","translation":"Success depends not only on talent but also on hard work."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erfassen'' means?","options":["to encompass/cover","to capture","to grasp","to include"],"correctAnswer":"to encompass/cover"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digital transformation encompasses all areas of the company and requires not only technological but also cultural changes.","options":["Die digitale Transformation erfasst alle Unternehmensbereiche und erfordert nicht nur technologische, sondern auch kulturelle Veränderungen.","Digitale Transformation braucht Technologie und Kulturwandel.","Alle Bereiche sind von der digitalen Transformation betroffen.","Technologie allein reicht für digitale Transformation nicht aus."],"correctAnswer":"Die digitale Transformation erfasst alle Unternehmensbereiche und erfordert nicht nur technologische, sondern auch kulturelle Veränderungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Wandel erfordert nicht nur neue Fähigkeiten, sondern auch eine neue ___.","options":["Denkweise","Methode","Herangehensweise","Strategie"],"correctAnswer":"Denkweise"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Success depends not only on talent but also on hard work","wordBankItems":["Erfolg","hängt","nicht","nur","von","Talent",",","sondern","auch","von","harter","Arbeit","ab","."],"correctAnswer":"Erfolg hängt nicht nur von Talent , sondern auch von harter Arbeit ab ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Vernetzung'' means?","options":["interconnection/networking","connection","network","linkage"],"correctAnswer":"interconnection/networking"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001cf',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss AI at B2","Use KI vocabulary","Talk about AI ethics and applications"],"explanation":{"intro":"AI vocabulary covers machine learning, ethics, and societal impact at B2.","culturalNote":"Germany''s KI-Strategie (AI strategy 2018) aims to make Germany a leading AI nation. Key institutions: DFKI (Deutsches Forschungszentrum für Künstliche Intelligenz). Key debates: KI und Arbeitsmarkt (AI and labour market — automation fears), KI-Regulierung (AI regulation — EU AI Act), Deepfakes, algorithmische Diskriminierung. Germany emphasises vertrauenswürdige KI (trustworthy AI)."},"examples":[{"german":"Maschinelles Lernen ermöglicht es Computern, aus Daten zu lernen und Muster zu erkennen, ohne explizit programmiert worden zu sein.","english":"Machine learning enables computers to learn from data and recognise patterns without having been explicitly programmed."},{"german":"Algorithmische Entscheidungssysteme werfen grundlegende Fragen nach Transparenz, Fairness und menschlicher Kontrolle auf.","english":"Algorithmic decision systems raise fundamental questions about transparency, fairness, and human control."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss AI, machine learning, and AI ethics at B2."}}',
'{"items":[{"word":"maschinelles Lernen","translation":"machine learning","pronunciation":"mah-SHEE-nel-es LER-nen","example":"Maschinelles Lernen."},{"word":"das Muster","translation":"pattern","pronunciation":"dahs MOOS-ter","example":"Muster erkennen."},{"word":"explizit","translation":"explicitly","pronunciation":"ek-splee-TSEET","example":"Explizit programmiert."},{"word":"algorithmisch","translation":"algorithmic","pronunciation":"al-go-RIT-mish","example":"Algorithmisch."},{"word":"die Transparenz","translation":"transparency","pronunciation":"dee trans-pah-RENTS","example":"Transparenz."},{"word":"vertrauenswürdig","translation":"trustworthy","pronunciation":"fer-TROW-ens-vür-dikh","example":"Vertrauenswürdige KI."}]}',
'{"title":"Ohne...zu + Passiv-Infinitiv — without having been (passive infinitive)","pattern":"ohne + Passiv-Infinitiv (worden zu sein) = without having been (done)","explanation":"Ohne explizit programmiert worden zu sein = without having been explicitly programmed. This is the passive perfect infinitive used in an ohne...zu construction. Structure: ohne + [past participle] + worden zu sein. Very advanced B2/C1 construction. Simpler equivalent: ohne dass man sie explizit programmiert hat. The passive infinitive appears in formal academic/technical German to describe processes where the subject was acted upon.","examples":[{"sentence":"Das System lernte, ohne jemals trainiert worden zu sein.","translation":"The system learnt without ever having been trained."},{"sentence":"Sie wurde befördert, ohne direkt beworben worden zu sein.","translation":"She was promoted without having directly applied."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Muster'' means?","options":["pattern","model","template","example"],"correctAnswer":"pattern"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Machine learning enables computers to learn from data and recognise patterns without having been explicitly programmed.","options":["Maschinelles Lernen ermöglicht es Computern, aus Daten zu lernen und Muster zu erkennen, ohne explizit programmiert worden zu sein.","Computer können durch maschinelles Lernen Muster erkennen.","KI lernt aus Daten ohne Programmierung.","Maschinelles Lernen braucht keine explizite Programmierung."],"correctAnswer":"Maschinelles Lernen ermöglicht es Computern, aus Daten zu lernen und Muster zu erkennen, ohne explizit programmiert worden zu sein."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das System lernte, ohne jemals trainiert worden zu ___.","options":["sein","haben","werden","gewesen"],"correctAnswer":"sein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She was promoted without having directly applied","wordBankItems":["Sie","wurde","befördert",",","ohne","direkt","beworben","worden","zu","sein","."],"correctAnswer":"Sie wurde befördert , ohne direkt beworben worden zu sein ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vertrauenswürdig'' means?","options":["trustworthy","reliable","credible","dependable"],"correctAnswer":"trustworthy"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001d0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss blockchain at B2","Use Blockchain vocabulary","Talk about decentralisation"],"explanation":{"intro":"Blockchain vocabulary covers distributed ledgers, cryptocurrencies, and decentralisation at B2.","culturalNote":"Germany was one of the first countries to recognise Bitcoin as Rechnungseinheit (unit of account) in 2013. BaFin (Bundesanstalt für Finanzdienstleistungsaufsicht) regulates crypto. Key concepts: dezentrale Technologie (decentralised technology), Smart Contracts, NFT (Non-Fungible Token), DeFi (dezentralisierte Finanzen). Germany''s Blockchain-Strategie (2019) supports the technology."},"examples":[{"german":"Die Blockchain-Technologie ermöglicht dezentrale Transaktionen ohne vertrauenswürdige Zwischeninstanz.","english":"Blockchain technology enables decentralised transactions without a trusted intermediary."},{"german":"Smart Contracts sind selbstausführende Programme, die Vertragsbedingungen automatisch überprüfen und durchsetzen.","english":"Smart contracts are self-executing programs that automatically verify and enforce contract terms."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss blockchain, smart contracts, and decentralised technology at B2."}}',
'{"items":[{"word":"dezentral","translation":"decentralised","pronunciation":"deh-tsen-TRAHL","example":"Dezentrale Technologie."},{"word":"die Zwischeninstanz","translation":"intermediary","pronunciation":"dee TSVI-shen-in-stants","example":"Ohne Zwischeninstanz."},{"word":"selbstausführend","translation":"self-executing","pronunciation":"ZELPST-ows-fü-rend","example":"Selbstausführendes Programm."},{"word":"durchsetzen","translation":"to enforce/implement","pronunciation":"DOORKH-zetsen","example":"Bedingungen durchsetzen."},{"word":"überprüfen","translation":"to verify/check","pronunciation":"ü-ber-PRÜ-fen","example":"Bedingungen überprüfen."},{"word":"die Vertragsbedingung","translation":"contract term","pronunciation":"dee fer-TRAHKS-beh-ding-oong","example":"Vertragsbedingungen."}]}',
'{"title":"Ohne + accusative — without (no verb)","pattern":"ohne + accusative noun (no verb) = without [something] — simple prepositional phrase","explanation":"Ohne + accusative = without (noun/pronoun, no verb). Ohne Zwischeninstanz = without an intermediary. Ohne Zweifel = without doubt. Ohne Frage = without question. When there IS a verb, use ohne...zu (same subject) or ohne dass (different subject). Ohne + noun is the simplest form: ohne Geld (without money), ohne Erlaubnis (without permission), ohne Aufwand (without effort). Very common at all levels but B2 learners should master all three forms.","examples":[{"sentence":"Sie hat die Aufgabe ohne Hilfe gelöst.","translation":"She solved the task without help."},{"sentence":"Ohne Vertrauen ist keine Zusammenarbeit möglich.","translation":"Without trust, no cooperation is possible."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Dezentral'' means?","options":["decentralised","distributed","dispersed","non-central"],"correctAnswer":"decentralised"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Blockchain technology enables decentralised transactions without a trusted intermediary.","options":["Die Blockchain-Technologie ermöglicht dezentrale Transaktionen ohne vertrauenswürdige Zwischeninstanz.","Blockchain macht Transaktionen ohne Mittler möglich.","Dezentrale Blockchain-Transaktionen brauchen keine Banken.","Blockchain funktioniert ohne Zwischeninstanz."],"correctAnswer":"Die Blockchain-Technologie ermöglicht dezentrale Transaktionen ohne vertrauenswürdige Zwischeninstanz."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ohne Vertrauen ist keine Zusammenarbeit ___.","options":["möglich","machbar","denkbar","vorstellbar"],"correctAnswer":"möglich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She solved the task without help","wordBankItems":["Sie","hat","die","Aufgabe","ohne","Hilfe","gelöst","."],"correctAnswer":"Sie hat die Aufgabe ohne Hilfe gelöst ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Durchsetzen'' means?","options":["to enforce/implement","to carry through","to achieve","to push through"],"correctAnswer":"to enforce/implement"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001d1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss cybersecurity at B2","Use Cybersicherheit vocabulary","Talk about threats and data protection"],"explanation":{"intro":"Cybersecurity vocabulary covers threats, attacks, and digital defence at B2.","culturalNote":"Germany faces significant cyber threats. BSI (Bundesamt für Sicherheit in der Informationstechnik) is the federal cybersecurity authority. Key threats: Ransomware-Angriffe (ransomware attacks — hospitals and municipalities targeted), Phishing, DDoS-Attacken, Industriespionage (industrial espionage — Germany is a prime target). The NIS2-Richtlinie (EU) tightens cybersecurity requirements."},"examples":[{"german":"Cyberkriminalität verursacht jährlich Schäden in Milliardenhöhe und gefährdet sowohl Unternehmen als auch staatliche Infrastrukturen.","english":"Cybercrime causes damage running into the billions annually and endangers both companies and state infrastructure."},{"german":"Präventive Cybersicherheitsmaßnahmen sind unerlässlich, da reaktive Strategien oft erst nach erheblichen Schäden greifen.","english":"Preventive cybersecurity measures are indispensable, as reactive strategies often only take effect after considerable damage."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss cybersecurity, cyber threats, and digital defence at B2."}}',
'{"items":[{"word":"unerlässlich","translation":"indispensable/essential","pronunciation":"oon-er-LES-likh","example":"Unerlässlich."},{"word":"reaktiv","translation":"reactive","pronunciation":"reh-ak-TEEF","example":"Reaktive Strategie."},{"word":"greifen","translation":"to take effect/work","pronunciation":"GRY-fen","example":"Maßnahmen greifen."},{"word":"erheblich","translation":"considerable/significant","pronunciation":"er-HEP-likh","example":"Erhebliche Schäden."},{"word":"verursachen","translation":"to cause","pronunciation":"fer-OOR-zakh-en","example":"Schäden verursachen."},{"word":"gefährden","translation":"to endanger","pronunciation":"geh-FÄR-den","example":"Infrastrukturen gefährden."}]}',
'{"title":"Greifen — to take effect, bite, work (of measures)","pattern":"Maßnahmen greifen = measures take effect/work (intransitive — the measure ''bites'')","explanation":"Greifen (intransitive) = to take effect, to work, to bite (of measures, laws, or strategies). Die Maßnahme greift = The measure is working. Die Bremse greift = The brake bites. Reactive strategies greifen erst nach Schäden = only take effect after damage. Perfect: hat gegriffen. Compare: wirken (to work/have an effect — broader), funktionieren (to work/function — more technical), anschlagen (to work/take effect — often medicine or treatment).","examples":[{"sentence":"Die neuen Regeln haben noch nicht gegriffen.","translation":"The new rules have not yet taken effect."},{"sentence":"Die Sparmaßnahmen greifen langsam, aber sicher.","translation":"The austerity measures are slowly but surely taking effect."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unerlässlich'' means?","options":["indispensable/essential","necessary","required","unavoidable"],"correctAnswer":"indispensable/essential"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Preventive cybersecurity measures are indispensable, as reactive strategies often only take effect after considerable damage.","options":["Präventive Cybersicherheitsmaßnahmen sind unerlässlich, da reaktive Strategien oft erst nach erheblichen Schäden greifen.","Prävention ist besser als Reaktion bei Cyberangriffen.","Reaktive Maßnahmen sind zu spät.","Cybersicherheit muss präventiv sein."],"correctAnswer":"Präventive Cybersicherheitsmaßnahmen sind unerlässlich, da reaktive Strategien oft erst nach erheblichen Schäden greifen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die neuen Regeln haben noch nicht ___.","options":["gegriffen","gewirkt","funktioniert","angeschlagen"],"correctAnswer":"gegriffen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The austerity measures are slowly but surely taking effect","wordBankItems":["Die","Sparmaßnahmen","greifen","langsam",",","aber","sicher","."],"correctAnswer":"Die Sparmaßnahmen greifen langsam , aber sicher ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erheblich'' means?","options":["considerable/significant","large","heavy","substantial"],"correctAnswer":"considerable/significant"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001d2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss platform economy at B2","Use Plattformökonomie vocabulary","Talk about network effects and gig work"],"explanation":{"intro":"Platform economy vocabulary covers digital platforms, network effects, and gig work at B2.","culturalNote":"Key platforms in Germany: Amazon, Uber (restricted), Lieferando (food delivery), Airbnb, Zalando. Key concepts: Netzwerkeffekte (network effects — more users = more value), Plattformregulierung (platform regulation — EU Digital Markets Act), Gigworker (gig economy workers — precarious employment), Datenmacht (data power of platforms). Germany strongly supports EU platform regulation."},"examples":[{"german":"Digitale Plattformen profitieren von Netzwerkeffekten: Je mehr Nutzer eine Plattform hat, desto wertvoller wird sie für alle Teilnehmer.","english":"Digital platforms benefit from network effects: the more users a platform has, the more valuable it becomes for all participants."},{"german":"Die Regulierung von Plattformmonopolen ist eine der zentralen wirtschaftspolitischen Herausforderungen des digitalen Zeitalters.","english":"The regulation of platform monopolies is one of the central economic policy challenges of the digital age."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss platform economy, network effects, and platform regulation at B2."}}',
'{"items":[{"word":"der Netzwerkeffekt","translation":"network effect","pronunciation":"dayr NETS-verk-eh-fekt","example":"Netzwerkeffekte."},{"word":"profitieren von","translation":"to benefit from","pronunciation":"pro-fi-TEER-en fon","example":"Von Netzwerkeffekten profitieren."},{"word":"je...desto","translation":"the more...the more","pronunciation":"yeh...DES-toh","example":"Je mehr...desto wertvoller."},{"word":"der Teilnehmer","translation":"participant","pronunciation":"dayr TYL-nay-mer","example":"Alle Teilnehmer."},{"word":"das Zeitalter","translation":"age/era","pronunciation":"dahs TSYT-al-ter","example":"Digitales Zeitalter."},{"word":"die Datenmacht","translation":"data power","pronunciation":"dee DAH-ten-makht","example":"Datenmacht der Plattformen."}]}',
'{"title":"Je...desto — the more...the more (proportional correlation)","pattern":"Je + comparative, desto/umso + comparative = the more X, the more Y","explanation":"Je...desto/umso = the more...the more (proportional). Je mehr Nutzer, desto wertvoller = The more users, the more valuable. Structure: Je + [comparative adjective/adverb + clause], desto/umso + [comparative + main clause]. The desto/umso clause has inverted word order (V1). Umso is slightly more colloquial than desto. Both are correct. Common patterns: je größer...desto besser, je früher...desto besser, je mehr...umso weniger.","examples":[{"sentence":"Je mehr du übst, desto besser wird dein Deutsch.","translation":"The more you practise, the better your German becomes."},{"sentence":"Je komplexer das System, umso schwieriger ist die Fehlersuche.","translation":"The more complex the system, the more difficult the troubleshooting."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Netzwerkeffekt'' means?","options":["network effect","network impact","connectivity effect","scale effect"],"correctAnswer":"network effect"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digital platforms benefit from network effects: the more users a platform has, the more valuable it becomes for all participants.","options":["Digitale Plattformen profitieren von Netzwerkeffekten: Je mehr Nutzer eine Plattform hat, desto wertvoller wird sie für alle Teilnehmer.","Plattformen werden wertvoller mit mehr Nutzern.","Je mehr Nutzer, desto besser für die Plattform.","Netzwerkeffekte machen Plattformen wertvoller."],"correctAnswer":"Digitale Plattformen profitieren von Netzwerkeffekten: Je mehr Nutzer eine Plattform hat, desto wertvoller wird sie für alle Teilnehmer."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Je mehr du übst, ___ besser wird dein Deutsch.","options":["desto","umso","je","so"],"correctAnswer":"desto"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The more complex the system the more difficult the troubleshooting","wordBankItems":["Je","komplexer","das","System",",","umso","schwieriger","ist","die","Fehlersuche","."],"correctAnswer":"Je komplexer das System , umso schwieriger ist die Fehlersuche ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Zeitalter'' means?","options":["age/era","time period","epoch","century"],"correctAnswer":"age/era"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001d3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss e-commerce at B2","Use E-Commerce vocabulary","Talk about online retail and logistics"],"explanation":{"intro":"E-commerce vocabulary covers online retail, logistics, and consumer protection at B2.","culturalNote":"Germany is the 2nd largest e-commerce market in Europe. Key players: Amazon, Zalando, Otto. Key concepts: Retourenquote (return rate — very high in Germany, 40-70% in fashion), Verbraucherschutz (consumer protection — strong in Germany, 14-day Widerrufsrecht), Zahlungsverkehr (payment processing — Germans prefer Rechnung/invoice and SEPA direct debit over credit cards), Logistikinfrastruktur."},"examples":[{"german":"Der E-Commerce-Boom hat traditionelle Einzelhändler unter erheblichen Anpassungsdruck gesetzt.","english":"The e-commerce boom has put considerable pressure on traditional retailers to adapt."},{"german":"Verbraucher in Deutschland profitieren von einem 14-tägigen Widerrufsrecht, das ihnen ermöglicht, online bestellte Waren problemlos zurückzugeben.","english":"Consumers in Germany benefit from a 14-day right of withdrawal, which allows them to return goods ordered online without difficulty."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss e-commerce, consumer rights, and online retail at B2."}}',
'{"items":[{"word":"der Anpassungsdruck","translation":"pressure to adapt","pronunciation":"dayr AN-pas-oonks-drook","example":"Anpassungsdruck."},{"word":"das Widerrufsrecht","translation":"right of withdrawal","pronunciation":"dahs VEE-der-rooFs-rekht","example":"14-tägiges Widerrufsrecht."},{"word":"zurückgeben","translation":"to return (goods)","pronunciation":"tsoo-RÜK-gay-ben","example":"Waren zurückgeben."},{"word":"problemlos","translation":"without difficulty/smoothly","pronunciation":"pro-BLAYM-lohs","example":"Problemlos zurückgeben."},{"word":"der Einzelhändler","translation":"retailer","pronunciation":"dayr YN-tsel-hend-ler","example":"Traditionelle Einzelhändler."},{"word":"profitieren von","translation":"to benefit from","pronunciation":"pro-fi-TEER-en fon","example":"Vom Widerrufsrecht profitieren."}]}',
'{"title":"Unter Druck setzen / unter Druck stehen — pressure idioms","pattern":"jemanden unter Druck setzen = to put under pressure; unter Druck stehen = to be under pressure","explanation":"Unter Druck setzen = to put under pressure (active, someone applies pressure). Unter erheblichen Anpassungsdruck setzen = to put under considerable pressure to adapt. Unter Druck stehen = to be under pressure (state). Unter Druck geraten = to come under pressure (dynamic — a change). Note: Anpassungsdruck is a compound meaning pressure to adapt. Der Druck as a noun appears in many fixed phrases in German business and political discourse.","examples":[{"sentence":"Die Konkurrenz setzt uns unter Druck.","translation":"The competition is putting us under pressure."},{"sentence":"Sie steht wegen der Deadline unter enormem Druck.","translation":"She is under enormous pressure because of the deadline."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Widerrufsrecht'' means?","options":["right of withdrawal","cancellation right","return right","revocation right"],"correctAnswer":"right of withdrawal"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The e-commerce boom has put considerable pressure on traditional retailers to adapt.","options":["Der E-Commerce-Boom hat traditionelle Einzelhändler unter erheblichen Anpassungsdruck gesetzt.","E-Commerce verdrängt traditionellen Einzelhandel.","Einzelhändler müssen sich dem E-Commerce anpassen.","Der Boom im Onlinehandel schadet dem stationären Handel."],"correctAnswer":"Der E-Commerce-Boom hat traditionelle Einzelhändler unter erheblichen Anpassungsdruck gesetzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Konkurrenz setzt uns unter ___.","options":["Druck","Stress","Zwang","Druck setzen"],"correctAnswer":"Druck"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She is under enormous pressure because of the deadline","wordBankItems":["Sie","steht","wegen","der","Deadline","unter","enormem","Druck","."],"correctAnswer":"Sie steht wegen der Deadline unter enormem Druck ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Problemlos'' means?","options":["without difficulty/smoothly","problem-free","effortlessly","without problems"],"correctAnswer":"without difficulty/smoothly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001d4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss data protection at B2","Use Datenschutz vocabulary","Talk about GDPR and privacy"],"explanation":{"intro":"Data protection vocabulary covers GDPR, privacy rights, and data security at B2.","culturalNote":"Germany is a world leader in data protection. The DSGVO (Datenschutz-Grundverordnung = GDPR) was strongly influenced by German law. Key concepts: Datensparsamkeit (data minimisation), Zweckbindung (purpose limitation), informationelle Selbstbestimmung (informational self-determination — German constitutional right from 1983 Volkszählungsurteil), Datenschutzbeauftragter (data protection officer — mandatory for many organisations)."},"examples":[{"german":"Die DSGVO räumt Verbrauchern umfangreiche Rechte ein, darunter das Recht auf Auskunft, Berichtigung und Löschung ihrer Daten.","english":"The GDPR grants consumers extensive rights, including the right to access, correction, and deletion of their data."},{"german":"Das Prinzip der Datensparsamkeit verlangt, dass nur diejenigen Daten erhoben werden, die für den jeweiligen Zweck unbedingt erforderlich sind.","english":"The principle of data minimisation requires that only those data be collected that are absolutely necessary for the respective purpose."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss GDPR, data protection rights, and privacy at B2."}}',
'{"items":[{"word":"einräumen","translation":"to grant/concede","pronunciation":"YN-roy-men","example":"Rechte einräumen."},{"word":"umfangreich","translation":"extensive/comprehensive","pronunciation":"OOM-fang-rykhh","example":"Umfangreiche Rechte."},{"word":"die Auskunft","translation":"access/information","pronunciation":"dee OWS-koonft","example":"Recht auf Auskunft."},{"word":"die Löschung","translation":"deletion","pronunciation":"dee LÖ-shoong","example":"Recht auf Löschung."},{"word":"unbedingt erforderlich","translation":"absolutely necessary","pronunciation":"OON-beh-dinkt er-FOR-der-likh","example":"Unbedingt erforderlich."},{"word":"erheben","translation":"to collect (data)","pronunciation":"er-HAY-ben","example":"Daten erheben."}]}',
'{"title":"Einräumen — to grant, concede, admit","pattern":"jemandem etwas einräumen = to grant someone something (rights, privileges, space)","explanation":"Einräumen (separable) = to grant, concede, allow, admit. Jemandem Rechte einräumen = to grant someone rights. Jemandem einen Spielraum einräumen = to give someone leeway. Also: etwas einräumen = to admit/concede something (e.g. einen Fehler einräumen = to admit a mistake). Perfect: hat eingeräumt. Compare: gewähren (to grant — more formal, often money/permission), zugestehen (to concede/grant — more reluctant), zugeben (to admit — personal faults).","examples":[{"sentence":"Das Gesetz räumt Mietern das Recht auf Mängelbeseitigung ein.","translation":"The law grants tenants the right to have defects remedied."},{"sentence":"Er räumte ein, dass sein Fehler Folgen hatte.","translation":"He admitted that his mistake had consequences."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Umfangreich'' means?","options":["extensive/comprehensive","broad","wide","detailed"],"correctAnswer":"extensive/comprehensive"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The GDPR grants consumers extensive rights, including the right to access, correction, and deletion of their data.","options":["Die DSGVO räumt Verbrauchern umfangreiche Rechte ein, darunter das Recht auf Auskunft, Berichtigung und Löschung ihrer Daten.","Die DSGVO schützt Verbraucherdaten.","Verbraucher haben nach der DSGVO viele Rechte.","Die DSGVO gibt Verbrauchern Kontrolle über ihre Daten."],"correctAnswer":"Die DSGVO räumt Verbrauchern umfangreiche Rechte ein, darunter das Recht auf Auskunft, Berichtigung und Löschung ihrer Daten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gesetz räumt Mietern das Recht auf Mängelbeseitigung ___.","options":["ein","zu","an","hin"],"correctAnswer":"ein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He admitted that his mistake had consequences","wordBankItems":["Er","räumte","ein",",","dass","sein","Fehler","Folgen","hatte","."],"correctAnswer":"Er räumte ein , dass sein Fehler Folgen hatte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erheben'' in ''Daten erheben'' means?","options":["to collect (data)","to raise","to gather","to survey"],"correctAnswer":"to collect (data)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001d5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss media law at B2","Use Medienrecht vocabulary","Talk about press law and defamation"],"explanation":{"intro":"Media law vocabulary covers press freedom, defamation, and media regulation at B2.","culturalNote":"Key concepts: Pressefreiheit (press freedom — Art. 5 GG), Verleumdung (defamation — criminal: §186-187 StGB), Gegendarstellung (right of reply), Impressumspflicht (imprint requirement), Medienstaatsvertrag (Interstate Media Treaty). Germany has strong Persönlichkeitsrechte (personality rights) — even public figures have a Privatsphäre (private sphere). Key institutions: Presserat (Press Council — self-regulatory), Landesmedienanstalten (state media authorities)."},"examples":[{"german":"Das allgemeine Persönlichkeitsrecht schützt Individuen vor unzulässigen Eingriffen in ihre Privatsphäre auch durch die Medien.","english":"The general right of personality protects individuals from inadmissible intrusions into their private sphere, including by the media."},{"german":"Zwischen dem Recht auf freie Meinungsäußerung und dem Schutz der Persönlichkeitsrechte besteht ein dauerhaftes Spannungsverhältnis.","english":"Between the right to freedom of expression and the protection of personality rights, there is a permanent tension."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss media law, personality rights, and press freedom at B2."}}',
'{"items":[{"word":"unzulässig","translation":"inadmissible/impermissible","pronunciation":"OON-tsoo-les-ikh","example":"Unzulässiger Eingriff."},{"word":"der Eingriff","translation":"intrusion/intervention","pronunciation":"dayr YN-grif","example":"Eingriff in die Privatsphäre."},{"word":"das Spannungsverhältnis","translation":"tension/tense relationship","pronunciation":"dahs SHPAN-oonks-fer-hält-nis","example":"Spannungsverhältnis."},{"word":"dauerhaft","translation":"permanent/lasting","pronunciation":"DOW-er-haft","example":"Dauerhaftes Spannungsverhältnis."},{"word":"die Meinungsäußerung","translation":"expression of opinion","pronunciation":"dee MY-noonks-oy-seh-roong","example":"Freie Meinungsäußerung."},{"word":"bestehen","translation":"to exist/persist","pronunciation":"beh-SHTAY-en","example":"Ein Spannungsverhältnis besteht."}]}',
'{"title":"Zwischen...besteht ein Spannungsverhältnis — permanent tension exists between","pattern":"Zwischen X und Y besteht ein Spannungsverhältnis = there is a tension between X and Y (formal analytical framing)","explanation":"Besteht ein Spannungsverhältnis = there is a (structural/permanent) tension. This is a key B2 academic phrase for describing structural conflicts. Spannungsverhältnis = tension, tense relationship (more analytical than Konflikt). Zwischen Freiheit und Sicherheit besteht ein Spannungsverhältnis = Between freedom and security there is a tension. Also: ein Spannungsfeld (an arena/field of tension — similar but more spatial), widerstreitende Interessen (conflicting interests — more adversarial).","examples":[{"sentence":"Zwischen wirtschaftlichem Wachstum und Umweltschutz besteht ein dauerhaftes Spannungsverhältnis.","translation":"Between economic growth and environmental protection, there is a permanent tension."},{"sentence":"Das Spannungsverhältnis zwischen Individuum und Gesellschaft ist ein zentrales Thema der Soziologie.","translation":"The tension between individual and society is a central theme of sociology."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unzulässig'' means?","options":["inadmissible/impermissible","unlawful","forbidden","illegal"],"correctAnswer":"inadmissible/impermissible"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Between the right to freedom of expression and the protection of personality rights, there is a permanent tension.","options":["Zwischen dem Recht auf freie Meinungsäußerung und dem Schutz der Persönlichkeitsrechte besteht ein dauerhaftes Spannungsverhältnis.","Meinungsfreiheit und Persönlichkeitsrechte stehen im Konflikt.","Es gibt einen Konflikt zwischen Meinungsfreiheit und Persönlichkeitsrechten.","Die Medien müssen Meinungsfreiheit und Persönlichkeitsrechte abwägen."],"correctAnswer":"Zwischen dem Recht auf freie Meinungsäußerung und dem Schutz der Persönlichkeitsrechte besteht ein dauerhaftes Spannungsverhältnis."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Zwischen wirtschaftlichem Wachstum und Umweltschutz besteht ein dauerhaftes ___.","options":["Spannungsverhältnis","Konflikt","Problem","Widerspruch"],"correctAnswer":"Spannungsverhältnis"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The tension between individual and society is a central theme of sociology","wordBankItems":["Das","Spannungsverhältnis","zwischen","Individuum","und","Gesellschaft","ist","ein","zentrales","Thema","der","Soziologie","."],"correctAnswer":"Das Spannungsverhältnis zwischen Individuum und Gesellschaft ist ein zentrales Thema der Soziologie ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Dauerhaft'' means?","options":["permanent/lasting","durable","long-term","enduring"],"correctAnswer":"permanent/lasting"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001d6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss press freedom at B2","Use Pressefreiheit vocabulary","Talk about journalism and democracy"],"explanation":{"intro":"Press freedom vocabulary covers journalism, censorship, and media pluralism at B2.","culturalNote":"Germany ranks highly in press freedom (RSF index — typically top 10). Key principles: Pressefreiheit (Art. 5 GG), Redaktionsgeheimnis (editorial secrecy), Zensurverbot (ban on censorship). Challenges: Lokalzeitungssterben (death of local newspapers), Konzentration (media concentration — Axel Springer, Bertelsmann), Staatsferne (independence from state). Public broadcasting: ARD, ZDF funded by Rundfunkbeitrag (broadcasting fee)."},"examples":[{"german":"Eine freie Presse gilt als unverzichtbare Säule der Demokratie, da sie staatliches Handeln kontrolliert und die Öffentlichkeit informiert.","english":"A free press is regarded as an indispensable pillar of democracy, as it monitors governmental action and informs the public."},{"german":"Medienpluralismus setzt voraus, dass verschiedene Stimmen und Perspektiven gleichberechtigt im öffentlichen Diskurs vertreten sind.","english":"Media pluralism presupposes that different voices and perspectives are represented on an equal footing in public discourse."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss press freedom, journalism, and media pluralism at B2."}}',
'{"items":[{"word":"unverzichtbar","translation":"indispensable","pronunciation":"oon-fer-TSIKHT-bar","example":"Unverzichtbare Säule."},{"word":"die Säule","translation":"pillar","pronunciation":"dee ZOY-leh","example":"Säule der Demokratie."},{"word":"gleichberechtigt","translation":"on an equal footing","pronunciation":"GLYKH-beh-rekh-tikt","example":"Gleichberechtigt vertreten."},{"word":"vertreten sein","translation":"to be represented","pronunciation":"fer-TRAY-ten zyn","example":"Im Diskurs vertreten sein."},{"word":"der Pluralismus","translation":"pluralism","pronunciation":"dayr ploo-rah-LIS-moos","example":"Medienpluralismus."},{"word":"die Öffentlichkeit","translation":"the public","pronunciation":"dee ÖF-fent-likh-kyt","example":"Die Öffentlichkeit informieren."}]}',
'{"title":"Als...gelten — revisited at B2 with complex nominal structures","pattern":"[complex noun phrase] gilt als [predicate noun/adjective] = is regarded as (nominal style)","explanation":"Recap and extend: als X gelten with complex noun phrases. Eine freie Presse gilt als unverzichtbare Säule der Demokratie = A free press is regarded as an indispensable pillar of democracy. Note the extended nominal structure: unverzichtbare Säule der Demokratie (indispensable pillar of democracy) is the predicate. In academic German, these predicate nominals can be very long and complex. The als remains regardless of how complex the predicate becomes.","examples":[{"sentence":"Diese Entdeckung gilt als Meilenstein der modernen Medizin.","translation":"This discovery is regarded as a milestone of modern medicine."},{"sentence":"Das Werk gilt als eines der bedeutendsten des 20. Jahrhunderts.","translation":"The work is regarded as one of the most significant of the 20th century."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unverzichtbar'' means?","options":["indispensable","essential","necessary","irreplaceable"],"correctAnswer":"indispensable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A free press is regarded as an indispensable pillar of democracy, as it monitors governmental action and informs the public.","options":["Eine freie Presse gilt als unverzichtbare Säule der Demokratie, da sie staatliches Handeln kontrolliert und die Öffentlichkeit informiert.","Die Presse kontrolliert die Regierung und informiert die Öffentlichkeit.","Pressefreiheit ist wichtig für die Demokratie.","Eine freie Presse überwacht staatliches Handeln."],"correctAnswer":"Eine freie Presse gilt als unverzichtbare Säule der Demokratie, da sie staatliches Handeln kontrolliert und die Öffentlichkeit informiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Entdeckung gilt als Meilenstein der modernen ___.","options":["Medizin","Wissenschaft","Forschung","Pharmazie"],"correctAnswer":"Medizin"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The work is regarded as one of the most significant of the 20th century","wordBankItems":["Das","Werk","gilt","als","eines","der","bedeutendsten","des","20.","Jahrhunderts","."],"correctAnswer":"Das Werk gilt als eines der bedeutendsten des 20. Jahrhunderts ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gleichberechtigt'' means?","options":["on an equal footing","equally","equal","with equal rights"],"correctAnswer":"on an equal footing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

